edges = [(i, i+1) for i in range(19)] + [(0, 19), (0, 7)]
print(len(edges), edges)

# Check girth via BFS
from collections import defaultdict, deque
adj = defaultdict(set)
for u,v in edges:
    adj[u].add(v); adj[v].add(u)

def girth(adj, n):
    g = float('inf')
    for s in range(n):
        dist = {s:0}; parent={s:-1}
        q=deque([s])
        while q:
            u=q.popleft()
            for v in adj[u]:
                if v not in dist:
                    dist[v]=dist[u]+1; parent[v]=u; q.append(v)
                elif parent[u]!=v:
                    g=min(g, dist[u]+dist[v]+1)
    return g

print("girth:", girth(adj, 20))

